-- Import active professor candidates from official McMaster faculty directories.
-- Generated from the reviewed department-professor snapshot.
--
-- `verified_course` means a known course assignment. `department_candidate`
-- means the person belongs to the course's department and is offered in the
-- rating picker without claiming that they have previously taught the course.
-- This migration adds 465 active people across 24 subjects.

BEGIN;

ALTER TABLE public.course_professors
  ADD COLUMN IF NOT EXISTS relationship_type TEXT NOT NULL DEFAULT 'verified_course',
  ADD COLUMN IF NOT EXISTS source_name TEXT,
  ADD COLUMN IF NOT EXISTS last_verified_at TIMESTAMPTZ;

ALTER TABLE public.course_professors
  DROP CONSTRAINT IF EXISTS course_professors_relationship_type_valid,
  ADD CONSTRAINT course_professors_relationship_type_valid
    CHECK (relationship_type IN ('verified_course', 'department_candidate'));

CREATE TEMP TABLE department_professor_seed (
  seed_id UUID NOT NULL,
  professor_name TEXT NOT NULL,
  subject TEXT NOT NULL,
  source_name TEXT NOT NULL,
  verified_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (seed_id, subject)
) ON COMMIT DROP;

