-- Reuse an existing professor identity when its normalized display name is
-- already present. Otherwise insert the deterministic source-derived UUID.
INSERT INTO public.professors (id, name)
SELECT DISTINCT ON (seed.seed_id)
  seed.seed_id,
  seed.professor_name
FROM department_professor_seed AS seed
WHERE NOT EXISTS (
  SELECT 1
  FROM public.professors AS professor
  WHERE lower(btrim(professor.name)) = lower(btrim(seed.professor_name))
)
ORDER BY seed.seed_id, seed.professor_name
ON CONFLICT (id) DO UPDATE
SET name = EXCLUDED.name;

WITH resolved_membership AS (
  SELECT
    course.id AS course_id,
    resolved_professor.id AS professor_id,
    seed.source_name,
    seed.verified_at
  FROM department_professor_seed AS seed
  JOIN public.courses AS course
    ON course.subject = seed.subject
  JOIN LATERAL (
    SELECT professor.id
    FROM public.professors AS professor
    WHERE lower(btrim(professor.name)) = lower(btrim(seed.professor_name))
    ORDER BY
      (professor.id = seed.seed_id) DESC,
      (
        SELECT COUNT(*)
        FROM public.course_professors AS existing_assignment
        WHERE existing_assignment.professor_id = professor.id
      ) DESC,
      professor.id
    LIMIT 1
  ) AS resolved_professor ON TRUE
)
INSERT INTO public.course_professors (
  course_id,
  professor_id,
  relationship_type,
  source_name,
  last_verified_at
)
SELECT
  membership.course_id,
  membership.professor_id,
  'department_candidate',
  membership.source_name,
  membership.verified_at
FROM resolved_membership AS membership
ON CONFLICT (course_id, professor_id) DO NOTHING;

CREATE INDEX IF NOT EXISTS course_professors_relationship_type_idx
  ON public.course_professors (relationship_type, course_id, professor_id);

COMMENT ON COLUMN public.course_professors.relationship_type IS
  'verified_course is a known teaching assignment; department_candidate is a broad rating-picker option from an official faculty directory.';

NOTIFY pgrst, 'reload schema';

COMMIT;
